## 5. Data Flow & State Management

### 5.1. RTK Query for API Calls

```ts
// services/api.ts
import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';

export const api = createApi({
  reducerPath: 'api',
  baseQuery: fetchBaseQuery({ baseUrl: '/api' }),
  tagTypes: ['Products', 'Cart'],
  endpoints: (builder) => ({
    getProducts: builder.query({
      query: ({ page, limit, filter }) => `/products?page=${page}&limit=${limit}&filter=${filter}`,
      providesTags: ['Products'],
    }),
    addToCart: builder.mutation({
      query: (productId) => ({
        url: `/cart`,
        method: 'POST',
        body: { productId },
      }),
      invalidatesTags: ['Cart'],
    }),
    // ...more endpoints
  }),
});

export const {
  useGetProductsQuery,
  useAddToCartMutation,
  // ...other hooks
} = api;
```

### 5.2. Redux Toolkit Slice for Cart

```ts
// store/cartSlice.ts
import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { RootState } from './store';

interface CartItem {
  id: string;
  quantity: number;
  price: number;
}

interface CartState {
  items: Record<string, CartItem>;
  total: number;
}

const initialState: CartState = {
  items: {},
  total: 0,
};

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem(state, action: PayloadAction<CartItem>) {
      const { id, quantity, price } = action.payload;
      if (state.items[id]) {
        state.items[id].quantity += quantity;
      } else {
        state.items[id] = { id, quantity, price };
      }
      state.total += price * quantity;
    },
    removeItem(state, action: PayloadAction<string>) {
      const id = action.payload;
      const item = state.items[id];
      if (item) {
        state.total -= item.price * item.quantity;
        delete state.items[id];
      }
    },
    clearCart(state) {
      state.items = {};
      state.total = 0;
    },
  },
});

export const { addItem, removeItem, clearCart } = cartSlice.actions;
export const selectCartItems = (state: RootState) => state.cart.items;
export const selectCartTotal = (state: RootState) => state.cart.total;
export default cartSlice.reducer;
```

### 5.3. Persisting State

```ts
// store/store.ts
import { configureStore } from '@reduxjs/toolkit';
import { api } from '../services/api';
import cartReducer from './cartSlice';
import storage from 'redux-persist/lib/storage';
import { persistReducer, persistStore } from 'redux-persist';

const persistConfig = {
  key: 'root',
  storage,
  whitelist: ['cart'], // only cart persists
};

const persistedCartReducer = persistReducer(persistConfig, cartReducer);

export const store = configureStore({
  reducer: {
    cart: persistedCartReducer,
    [api.reducerPath]: api.reducer,
  },
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware().concat(api.middleware),
});

export const persistor = persistStore(store);
```

